"""Materialize the single approved candidate only after the actual A gate."""
import hashlib,json,sys
from pathlib import Path
root=Path(__file__).resolve().parents[2];sys.path.insert(0,str(root/'Tools/MCP'))
from preflight import payload
folder=root/'Docs/Tests/SalvagePrototype/Evidence/LLMShortTasks/L02Q01'
result=payload(json.loads((folder/'Retrieval_B.json').read_text(encoding='utf-8-sig')))['data']
assert result['status']=='succeeded' and result['result']['summary']['total']==46 and result['result']['summary']['failed']==0,'Actual A gate has not passed'
rules=(root/'Docs/SalvagePrototype/L02_Q01_PromptV2_Draft.txt').read_text(encoding='utf-8-sig');assert '\r' not in rules
items=json.loads((root/'Docs/SalvagePrototype/L02_Q01_ExamplesV2_Draft.json').read_text(encoding='utf-8-sig'));assert len(items)==6
examples=[]
for r in items:
    targets=json.dumps([dict(id=r['targetId'],name=r['targetName'],actions=['investigate'])],ensure_ascii=False,separators=(',',':'))
    user='相关记忆（摘要）：\n[线索 '+r['targetId']+'] '+r['targetName']+'：'+r['report']+'\n允许目标（ID/名称/允许行为）：\n'+targets+'\n玩家问题：\n'+r['question']
    assistant=json.dumps(r['assistant'],ensure_ascii=False,separators=(',',':'));assert 0<len(user)<=200 and 0<len(assistant)<=512
    examples.append(dict(user=user,assistant=assistant))
literal=lambda s:json.dumps(s,ensure_ascii=False)
lines=['// Generated by q01_prepare_candidate.py; one approved candidate, old v1 unchanged.','using System;','using System.Collections.Generic;','using EchoStation.AI.Context;','using EchoStation.AI.Tokenization;','namespace EchoStation.L02','{','    public static class SceneQuestionPromptV2','    {','        public const string Text='+literal(rules)+';','        public static IReadOnlyList<Qwen3ChatExample> Examples {get;}=Array.AsReadOnly(new[]{']
lines+=['            new Qwen3ChatExample('+literal(e['user'])+','+literal(e['assistant'])+'),' for e in examples]
lines+=['        });','        public static Qwen3PromptProfile Profile {get;}=new Qwen3PromptProfile("l02_scene_v2_q01",Text,Qwen3PromptLayout.RulesSystemExamples,Examples);','    }','}']
target=root/'Assets/EchoStation/LLMShortTasks/L02/Service/SceneQuestionPromptV2.cs';assert not target.exists();target.write_bytes(('\n'.join(lines)+'\n').encode('utf-8'))
for name,data in [('PromptV2.txt',rules.encode('utf-8')),('ExamplesV2.json',json.dumps(examples,ensure_ascii=False,separators=(',',':')).encode('utf-8'))]:
    p=folder/name;assert not p.exists();p.write_bytes(data)
freeze={'profile':'l02_scene_v2_q01','promptSha256':hashlib.sha256(rules.encode('utf-8')).hexdigest(),'examplesSha256':hashlib.sha256((folder/'ExamplesV2.json').read_bytes()).hexdigest(),'examples':6,'candidateSourceSha256':hashlib.sha256(target.read_bytes()).hexdigest(),'realRequestsStarted':False}
p=folder/'Candidate_Freeze.json';assert not p.exists();p.write_text(json.dumps(freeze,indent=2),encoding='utf-8');print(json.dumps(freeze))
